from decimal import Decimal, InvalidOperation


def _value(mapping: dict | None, key: str) -> object:
    if not mapping:
        return ""
    value = mapping.get(key, "")
    return "" if value is None else value


def _number(value: object) -> Decimal:
    if value == "" or value is None:
        return Decimal("0")
    try:
        return Decimal(str(value).strip())
    except (InvalidOperation, ValueError):
        return Decimal("0")


def _lookup(
    tables: dict | None,
    table_name: str,
    key_col: str,
    key_val: object,
    out_col: str,
) -> object:
    if not tables:
        return ""

    rows = tables.get(table_name, ())
    for row in rows:
        if _value(row, "DEL_FLG") == "Y":
            continue
        if _value(row, key_col) == key_val:
            return _value(row, out_col)
    return ""


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    tables: dict | None = None,
    table: str = "ORD_HEADER",
) -> list[dict]:
    errors: list[dict] = []

    if table == "ORD_HEADER":
        if event in ("INSERT", "UPDATE"):
            discount = _number(_value(record, "DISC_PCT"))
            if not (discount >= 0 and discount <= 100):
                errors.append({
                    "code": "E5001",
                    "message": "Discount out of range",
                    "severity": "BLOCK",
                })

        if event == "UPDATE":
            discount = _number(_value(record, "DISC_PCT"))
            role = _lookup(
                tables,
                "USR_MASTER",
                "USR_ID",
                _value(record, "OWNER_UID"),
                "ROLE_ID",
            )
            if discount > 20 and role != "MGR" and role != "ADMIN":
                errors.append({
                    "code": "E5002",
                    "message": "Discount over 20 percent requires manager role",
                    "severity": "BLOCK",
                })

            old_status = _value(old, "STAT_CD")
            status = _value(record, "STAT_CD")
            if old_status == "I" and status != "I" and status != "X":
                errors.append({
                    "code": "E5003",
                    "message": "Invoiced order can only be cancelled",
                    "severity": "BLOCK",
                })

    elif table == "ORD_LINE":
        if event in ("INSERT", "UPDATE"):
            if not (_number(_value(record, "QTY")) > 0):
                errors.append({
                    "code": "E5004",
                    "message": "Quantity must be positive",
                    "severity": "BLOCK",
                })

        if event == "INSERT":
            active_flag = _lookup(
                tables,
                "PROD_MASTER",
                "PROD_ID",
                _value(record, "PROD_ID"),
                "ACTIVE_FLG",
            )
            if active_flag != "Y":
                errors.append({
                    "code": "E5005",
                    "message": "Product not active",
                    "severity": "BLOCK",
                })

    return errors


def is_blocked(errors: list[dict]) -> bool:
    return any(error.get("severity") == "BLOCK" for error in errors)
